        integer_part = int(decimal)
        decimal_part = decimal - integer_part
        binary_integer = bin(abs(integer_part))[2:]
        binary_decimal = ''
        while decimal_part != 0:
            decimal_part *= 2
            if decimal_part >= 1:
                binary_decimal += '1'
                decimal_part -= 1
            else:
                binary_decimal += '0'
        binary = 'db' + binary_integer + '.' + binary_decimal + 'db'
    return binary
